133	  /**
134	   * Read bytes from stream into a byte buffer using an
135	   * intermediate byte array.
136	   * @param length number of bytes to read.
137	   * @param buffer buffer to fill.
138	   * @param operation operation to use for reading data.
139	   * @throws IOException any IOE.
140	   */
141	  public static void readInDirectBuffer(int length,
142	                                        ByteBuffer buffer,
143	                                        Function4RaisingIOE<Integer, byte[], Integer,
144	                                                Integer, Void> operation) throws IOException {
145	    if (length == 0) {
146	      return;
147	    }
148	    int readBytes = 0;
149	    int position = 0;
150	    int tmpBufferMaxSize = Math.min(TMP_BUFFER_MAX_SIZE, length);
151	    byte[] tmp = new byte[tmpBufferMaxSize];
152	    while (readBytes < length) {
153	      int currentLength = (readBytes + tmpBufferMaxSize) < length ?
154	              tmpBufferMaxSize
155	              : (length - readBytes);
156	      operation.apply(position, tmp, 0, currentLength);
157	      buffer.put(tmp, 0, currentLength);
158	      position = position + currentLength;
159	      readBytes = readBytes + currentLength;
160	    }
161	  }
