435	    private void validateRangeRequest(List<? extends FileRange> ranges,
436	                                      final long fileLength) throws EOFException {
437	      for (FileRange range : ranges) {
438	        VectoredReadUtils.validateRangeRequest(range);
439	        if (range.getOffset() + range.getLength() > fileLength) {
440	          final String errMsg = String.format("Requested range [%d, %d) is beyond EOF for path %s",
441	                  range.getOffset(), range.getLength(), file);
442	          LOG.warn(errMsg);
443	          throw new EOFException(errMsg);
