449	    public void readVectored(List<? extends FileRange> ranges,
450	                             IntFunction<ByteBuffer> allocate) throws IOException {
451	      final long length = getFileLength();
452	      validateRangeRequest(ranges, length);
453	
454	      // If the stream doesn't have checksums, just delegate.
455	      if (sums == null) {
456	        datas.readVectored(ranges, allocate);
457	        return;
458	      }
459	      int minSeek = minSeekForVectorReads();
460	      int maxSize = maxReadSizeForVectorReads();
461	      List<CombinedFileRange> dataRanges =
462	          VectoredReadUtils.mergeSortedRanges(Arrays.asList(sortRanges(ranges)), bytesPerSum,
463	              minSeek, maxReadSizeForVectorReads());
464	      // While merging the ranges above, they are rounded up based on the value of bytesPerSum
465	      // which leads to some ranges crossing the EOF thus they need to be fixed else it will
466	      // cause EOFException during actual reads.
467	      for (CombinedFileRange range : dataRanges) {
468	        if (range.getOffset() + range.getLength() > length) {
469	          range.setLength((int) (length - range.getOffset()));
470	        }
471	      }
472	      List<CombinedFileRange> checksumRanges = findChecksumRanges(dataRanges,
473	          bytesPerSum, minSeek, maxSize);
474	      sums.readVectored(checksumRanges, allocate);
475	      datas.readVectored(dataRanges, allocate);
476	      for(CombinedFileRange checksumRange: checksumRanges) {
477	        for(FileRange dataRange: checksumRange.getUnderlying()) {
478	          // when we have both the ranges, validate the checksum
479	          CompletableFuture<ByteBuffer> result =
480	              checksumRange.getData().thenCombineAsync(dataRange.getData(),
481	                  (sumBuffer, dataBuffer) ->
482	                      checkBytes(sumBuffer, checksumRange.getOffset(),
483	                          dataBuffer, dataRange.getOffset(), bytesPerSum, file));
484	          // Now, slice the read data range to the user's ranges
485	          for(FileRange original: ((CombinedFileRange) dataRange).getUnderlying()) {
486	            original.setData(result.thenApply(
487	                (b) -> VectoredReadUtils.sliceTo(b, dataRange.getOffset(), original)));
488	          }
489	        }
490	      }
491	    }
